INSERT INTO `space_versions` (`version`, `title`, `summary`, `created_at`) VALUES
('v77', '网页智能体账号身份落库与串号防护', '起因：两个豆包智能体（豆包、傻包）登录的明明是不同账号，官网历史里却都落在同一个账号下。实测确认两份存好的 Cookie 各自打开官网页面，官网都报同一个账号（知梦方生）——第二份凭证复制时，它所在的浏览器会话实际还停在这个账号上，而空间此前只存了账号昵称、从不记录也不比对账号身份，这种串号在空间里看不出来。现在起每个网页智能体在验证登录时都会把官网自己报出的账号身份（豆包取官网页面里的 user_id，其余站点取官网返回的账号标识）与凭证本身各存一份哈希：验证后若发现同站另一个智能体指向同一账号，验证结果与设置页会明确报出「账号冲突」并写明处理办法，且冲突解除前空间会停止给冲突中的智能体发送（回复会直接说明原因），不再让消息继续进入错误账号的历史；某智能体的账号身份一旦变更，它名下旧账号的官网对话续接（豆包、DeepSeek）与豆包已识别菜单会被清掉，下一次发送按新账号重新开始，不再把旧账号的对话用新账号续发。豆包与 DeepSeek 每次发送前还会再核对一次实时账号身份，与保存时不一致就停发并说明，绝不静默发错账号。千问共用的 Baxia 指纹缓存改为按各自的浏览器 UA 分开，不再两个千问账号共用一份设备指纹。存量智能体的身份由本次更新后的一次性刷新动作按各自凭证向官网重新核对落库，两个豆包的冲突会随即在各自设置页显示。', 1795187400000);
